document.addEventListener("DOMContentLoaded",function(){let e=0,r=0,c=0,s=0,d=0,n=0,i=0,a=0,l=0,u=0,t=0,y=0,f=0;const S=document.querySelector("#individualReputation"),$=JSON.parse(S.getAttribute("data-rate"));f=Object.keys($),t=f.length,y=q(t,"rating","ratings"),t!=0&&($.forEach(o=>{o.calification==5?e+=1:o.calification==4?r+=1:o.calification==3?c+=1:o.calification==2?s+=1:o.calification==1&&(d+=1)}),n=e*100/t,i=r*100/t,a=c*100/t,l=s*100/t,u=d*100/t,document.querySelector("#star5").textContent=`${n} %`,document.querySelector("#star5color").style.width=`${n}%`,document.querySelector("#star4").textContent=`${i} %`,document.querySelector("#star4color").style.width=`${i}%`,document.querySelector("#star3").textContent=`${a} %`,document.querySelector("#star3color").style.width=`${a}%`,document.querySelector("#star2").textContent=`${l} %`,document.querySelector("#star2color").style.width=`${l}%`,document.querySelector("#star1").textContent=`${u} %`,document.querySelector("#star1color").style.width=`${u}%`,document.querySelector("#totalRating").textContent=y)});function q(e,r,c){return e===1?`${e} ${r}`:`${e} ${c}`}
